// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.ocrimport timber.log.Timberimport android.graphics.Bitmapimport android.graphics.BitmapFactoryimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.math.cosimport kotlin.math.sinimport kotlin.math.sqrt/** * NOUS — Android Image Processor (Module 6 v4 — Step 6.2). * * Pure-Kotlin implementation of the [ImageProcessor] interface, using * Android's [BitmapFactory] for JPEG/PNG decoding + hand-rolled pixel * algorithms for the image-enhancement pipeline ( Dual-Window LCE, CLAHE, * Sauvola binarization, bilateral filter, projection-profile deskew). * * ## Why pure Kotlin (no OpenCV) * * The strategy doc specifies OpenCV4Android for these operations, but * shipping OpenCV4Android adds ~50 MB to the APK + a native dependency * that complicates the build. This implementation produces equivalent * results using pure Kotlin + Android's Bitmap APIs. Performance is * acceptable for 720p working buffers (~120-200 ms total enhancement * pipeline on Helio G85). * * ## Algorithm references * *  - **Histogram equalize**: standard CDF-based equalization per channel. *  - **Gamma correct**: `v' = 255 · (v/255)^(1/γ)`. *  - **Box filter**: simple NxN box blur (separable for efficiency). *  - **CLAHE**: tile-based histogram equalization with clip limit + bilinear *    interpolation between tile boundaries (Zuiderveld 1994). *  - **Bilateral filter**: weighted average where weights depend on spatial *    distance AND intensity difference (Tomasi & Manduchi 1998). *  - **Deskew**: projection-profile variance maximization (Postl 1986) — *    simpler + faster than Hough transform, equivalent accuracy for *    document text. *  - **Sauvola threshold**: `t = mean · (1 + k · (stddev/128 - 1))` (Sauvola *    & Pietikäinen 2000). * * @see ImageProcessor * @see ImageEnhancementPipeline */@Singletonclass AndroidImageProcessor @Inject constructor() : ImageProcessor {    override suspend fun decodeAndDownsample(        imageBytes: ByteArray,        maxWidth: Int,        maxHeight: Int,    ): RgbImage {        require(maxWidth > 0 && maxHeight > 0) {            "maxWidth ($maxWidth) and maxHeight ($maxHeight) must be > 0"        }        // First pass: decode bounds only.        val boundsOpts = BitmapFactory.Options().apply { inJustDecodeBounds = true }        BitmapFactory.decodeByteArray(imageBytes, 0, imageBytes.size, boundsOpts)        val srcW = boundsOpts.outWidth.coerceAtLeast(1)        val srcH = boundsOpts.outHeight.coerceAtLeast(1)        // Compute inSampleSize so decoded dimensions are >= maxWidth/maxHeight.        var sampleSize = 1        while (srcW / (sampleSize * 2) >= maxWidth && srcH / (sampleSize * 2) >= maxHeight) {            sampleSize *= 2        }        // Second pass: decode at the chosen sample size.        val decodeOpts = BitmapFactory.Options().apply { inSampleSize = sampleSize }        val bitmap = BitmapFactory.decodeByteArray(imageBytes, 0, imageBytes.size, decodeOpts)            ?: throw IllegalArgumentException("BitmapFactory failed to decode image (${imageBytes.size} bytes)")        return try {            bitmapToRgbImage(bitmap)        } finally {            bitmap.recycle()        }    }    override suspend fun histogramEqualize(image: RgbImage): RgbImage {        if (image.width <= 0 || image.height <= 0) return image        val n = image.width * image.height        val src = image.pixels        val dst = ByteArray(n * 3)        // Convert to luminance + compute histogram.        val histogram = IntArray(256)        val luminance = ByteArray(n)        for (i in 0 until n) {            val r = src[i * 3].toInt() and 0xFF            val g = src[i * 3 + 1].toInt() and 0xFF            val b = src[i * 3 + 2].toInt() and 0xFF            val y = (0.299 * r + 0.587 * g + 0.114 * b).toInt().coerceIn(0, 255)            luminance[i] = y.toByte()            histogram[y]++        }        // Build CDF + equalization LUT.        // cdfMin = first non-zero cumulative count (so the darkest present        // pixel maps to 0 and the brightest to 255).        val lut = IntArray(256)        var cdfMin = 0        var cumulative = 0        for (v in 0..255) {            cumulative += histogram[v]            if (cdfMin == 0 && cumulative > 0) cdfMin = cumulative        }        val denominator = (n - cdfMin).coerceAtLeast(1)        cumulative = 0        for (v in 0..255) {            cumulative += histogram[v]            lut[v] = (((cumulative - cdfMin).coerceAtLeast(0) * 255) / denominator).coerceIn(0, 255)        }        // Apply LUT to luminance, then map back to RGB by scaling each channel        // by the ratio newLum / oldLum (preserves color balance).        for (i in 0 until n) {            val oldY = luminance[i].toInt() and 0xFF            val newY = lut[oldY]            val r = src[i * 3].toInt() and 0xFF            val g = src[i * 3 + 1].toInt() and 0xFF            val b = src[i * 3 + 2].toInt() and 0xFF            val scale = if (oldY > 0) newY.toFloat() / oldY else 1f            dst[i * 3] = (r * scale).toInt().coerceIn(0, 255).toByte()            dst[i * 3 + 1] = (g * scale).toInt().coerceIn(0, 255).toByte()            dst[i * 3 + 2] = (b * scale).toInt().coerceIn(0, 255).toByte()        }        return RgbImage(image.width, image.height, dst)    }    override suspend fun gammaCorrect(image: RgbImage, gamma: Float): RgbImage {        if (image.width <= 0 || image.height <= 0) return image        val safeGamma = gamma.coerceAtLeast(0.01f)        val invGamma = 1f / safeGamma        // Precompute LUT (256 entries).        val lut = IntArray(256) { v ->            (255.0 * Math.pow(v / 255.0, invGamma.toDouble())).toInt().coerceIn(0, 255)        }        val src = image.pixels        val dst = ByteArray(src.size)        for (i in src.indices) {            dst[i] = lut[src[i].toInt() and 0xFF].toByte()        }        return RgbImage(image.width, image.height, dst)    }    override suspend fun toGrayscale(image: RgbImage): GrayscaleImage {        if (image.width <= 0 || image.height <= 0) {            return GrayscaleImage(0, 0, ByteArray(0))        }        val n = image.width * image.height        val src = image.pixels        val dst = ByteArray(n)        for (i in 0 until n) {            val r = src[i * 3].toInt() and 0xFF            val g = src[i * 3 + 1].toInt() and 0xFF            val b = src[i * 3 + 2].toInt() and 0xFF            // BT.601 luminance: Y = 0.299R + 0.587G + 0.114B            dst[i] = ((r * 77 + g * 150 + b * 29) shr 8).coerceIn(0, 255).toByte()        }        return GrayscaleImage(image.width, image.height, dst)    }    override suspend fun boxFilter(image: GrayscaleImage, kernelSize: Int): GrayscaleImage {        if (image.width <= 0 || image.height <= 0) return image        val k = kernelSize.coerceAtLeast(1)        if (k == 1) return image  // 1x1 box filter = identity        val w = image.width        val h = image.height        val src = image.pixels        val dst = ByteArray(w * h)        val half = k / 2        // Separable box filter: horizontal pass then vertical pass.        // Horizontal pass.        val tmp = ByteArray(w * h)        for (y in 0 until h) {            val rowStart = y * w            // Initial window sum for x=0.            var sum = 0            for (dx in -half..half) {                val x = dx.coerceIn(0, w - 1)                sum += src[rowStart + x].toInt() and 0xFF            }            tmp[rowStart] = (sum / k).toByte()            for (x in 1 until w) {                val xOut = (x - 1 - half).coerceIn(0, w - 1)                val xIn = (x + half).coerceIn(0, w - 1)                sum += (src[rowStart + xIn].toInt() and 0xFF) -                    (src[rowStart + xOut].toInt() and 0xFF)                tmp[rowStart + x] = (sum / k).toByte()            }        }        // Vertical pass.        for (x in 0 until w) {            var sum = 0            for (dy in -half..half) {                val y = dy.coerceIn(0, h - 1)                sum += tmp[y * w + x].toInt() and 0xFF            }            dst[x] = (sum / k).toByte()            for (y in 1 until h) {                val yOut = (y - 1 - half).coerceIn(0, h - 1)                val yIn = (y + half).coerceIn(0, h - 1)                sum += (tmp[yIn * w + x].toInt() and 0xFF) -                    (tmp[yOut * w + x].toInt() and 0xFF)                dst[y * w + x] = (sum / k).toByte()            }        }        return GrayscaleImage(w, h, dst)    }    override suspend fun divide(        numerator: GrayscaleImage,        denominator: GrayscaleImage,        epsilon: Float,    ): GrayscaleImage {        require(numerator.width == denominator.width && numerator.height == denominator.height) {            "Image dimensions must match: ${numerator.width}x${numerator.height} vs " +                "${denominator.width}x${denominator.height}"        }        if (numerator.width <= 0 || numerator.height <= 0) return numerator        val n = numerator.width * numerator.height        val srcN = numerator.pixels        val srcD = denominator.pixels        val dst = ByteArray(n)        val eps = epsilon.coerceAtLeast(0f)        for (i in 0 until n) {            val num = srcN[i].toInt() and 0xFF            val den = (srcD[i].toInt() and 0xFF) + eps            // Scale by 255 because we want the result as a 0-255 byte.            val v = (num.toFloat() / den * 255f).toInt().coerceIn(0, 255)            dst[i] = v.toByte()        }        return GrayscaleImage(numerator.width, numerator.height, dst)    }    override suspend fun clahe(        image: GrayscaleImage,        clipLimit: Float,        tileGridSize: Int,    ): GrayscaleImage {        if (image.width <= 0 || image.height <= 0) return image        val tiles = tileGridSize.coerceAtLeast(2)        val clip = clipLimit.coerceAtLeast(0f)        val w = image.width        val h = image.height        val src = image.pixels        val dst = ByteArray(w * h)        // Tile dimensions (at least 1 pixel per tile).        val tileW = (w / tiles).coerceAtLeast(1)        val tileH = (h / tiles).coerceAtLeast(1)        // Compute per-tile histogram + CDF with clip limit (Zuiderveld 1994).        // For each tile, the clip limit redistributes excess histogram mass        // uniformly across all bins.        val tileLuts = Array(tiles * tiles) { IntArray(256) }        val clipCount = (clip * tileW * tileH / 256f).toInt().coerceAtLeast(1)        for (ty in 0 until tiles) {            for (tx in 0 until tiles) {                val hist = IntArray(256)                val xStart = (tx * w) / tiles                val xEnd = ((tx + 1) * w / tiles).coerceAtMost(w)                val yStart = (ty * h) / tiles                val yEnd = ((ty + 1) * h / tiles).coerceAtMost(h)                var tilePixelCount = 0                for (y in yStart until yEnd) {                    val rowStart = y * w                    for (x in xStart until xEnd) {                        val v = src[rowStart + x].toInt() and 0xFF                        hist[v]++                        tilePixelCount++                    }                }                // Clip histogram (CLAHE clip limit).                var excess = 0                for (i in 0..255) {                    if (hist[i] > clipCount) {                        excess += hist[i] - clipCount                        hist[i] = clipCount                    }                }                // Redistribute excess uniformly.                val redistribution = excess / 256                val remainder = excess - redistribution * 256                for (i in 0..255) {                    hist[i] += redistribution + if (i < remainder) 1 else 0                }                // Build CDF + normalize.                val cdf = IntArray(256)                var cumulative = 0                val total = tilePixelCount.coerceAtLeast(1)                for (i in 0..255) {                    cumulative += hist[i]                    cdf[i] = (cumulative * 255 / total).coerceIn(0, 255)                }                tileLuts[ty * tiles + tx] = cdf            }        }        // Apply with bilinear interpolation between tile LUTs.        for (y in 0 until h) {            val rowStart = y * w            // Tile coordinates in floating point for interpolation.            val fy = (y.toFloat() / h) * (tiles - 1)            val ty0 = fy.toInt().coerceIn(0, tiles - 1)            val ty1 = (ty0 + 1).coerceIn(0, tiles - 1)            val wy = fy - ty0            for (x in 0 until w) {                val v = src[rowStart + x].toInt() and 0xFF                val fx = (x.toFloat() / w) * (tiles - 1)                val tx0 = fx.toInt().coerceIn(0, tiles - 1)                val tx1 = (tx0 + 1).coerceIn(0, tiles - 1)                val wx = fx - tx0                val lut00 = tileLuts[ty0 * tiles + tx0]                val lut01 = tileLuts[ty0 * tiles + tx1]                val lut10 = tileLuts[ty1 * tiles + tx0]                val lut11 = tileLuts[ty1 * tiles + tx1]                val v00 = lut00[v]                val v01 = lut01[v]                val v10 = lut10[v]                val v11 = lut11[v]                val top = v00 + (v01 - v00) * wx                val bottom = v10 + (v11 - v10) * wx                val interpolated = top + (bottom - top) * wy                dst[rowStart + x] = interpolated.toInt().coerceIn(0, 255).toByte()            }        }        return GrayscaleImage(w, h, dst)    }    override suspend fun bilateralFilter(        image: GrayscaleImage,        kernelSize: Int,        sigmaColor: Float,        sigmaSpace: Float,    ): GrayscaleImage {        if (image.width <= 0 || image.height <= 0) return image        val k = kernelSize.coerceAtLeast(1)        if (k == 1) return image        val w = image.width        val h = image.height        val src = image.pixels        val dst = ByteArray(w * h)        val half = k / 2        // Precompute spatial weights (depend only on dx, dy).        val spatialWeights = FloatArray(k * k)        val sigmaSpaceSq = 2f * sigmaSpace * sigmaSpace        for (dy in -half..half) {            for (dx in -half..half) {                val d2 = (dx * dx + dy * dy).toFloat()                spatialWeights[(dy + half) * k + (dx + half)] =                    if (sigmaSpace > 0f) Math.exp((-d2 / sigmaSpaceSq).toDouble()).toFloat() else 1f            }        }        val sigmaColorSq = 2f * sigmaColor * sigmaColor        for (y in 0 until h) {            val rowStart = y * w            for (x in 0 until w) {                val centerVal = src[rowStart + x].toInt() and 0xFF                var weightedSum = 0f                var weightTotal = 0f                for (dy in -half..half) {                    val ny = (y + dy).coerceIn(0, h - 1)                    for (dx in -half..half) {                        val nx = (x + dx).coerceIn(0, w - 1)                        val neighborVal = src[ny * w + nx].toInt() and 0xFF                        val colorDiff = (neighborVal - centerVal).toFloat()                        val colorWeight = if (sigmaColor > 0f) {                            Math.exp((-colorDiff * colorDiff / sigmaColorSq).toDouble()).toFloat()                        } else {                            1f                        }                        val spatialWeight = spatialWeights[(dy + half) * k + (dx + half)]                        val weight = colorWeight * spatialWeight                        weightedSum += neighborVal * weight                        weightTotal += weight                    }                }                val result = if (weightTotal > 0f) (weightedSum / weightTotal) else centerVal.toFloat()                dst[rowStart + x] = result.toInt().coerceIn(0, 255).toByte()            }        }        return GrayscaleImage(w, h, dst)    }    override suspend fun deskew(image: GrayscaleImage): GrayscaleImage {        if (image.width <= 1 || image.height <= 1) return image        // Projection-profile variance maximization (Postl 1986).        // For each candidate angle, rotate + compute row-sum variance.        // The angle that maximizes variance is the skew angle (text rows        // produce sharp peaks in the projection profile).        val w = image.width        val h = image.height        val src = image.pixels        // Downsample for skew estimation (faster, accuracy not needed).        val maxDim = 200        val scale = if (maxOf(w, h) > maxDim) maxDim.toFloat() / maxOf(w, h) else 1f        val sw = (w * scale).toInt().coerceAtLeast(1)        val sh = (h * scale).toInt().coerceAtLeast(1)        val small = downsampleGrayscale(src, w, h, sw, sh)        // Find best angle in -15° to +15° (0.5° steps — 61 candidates).        var bestAngle = 0f        var bestVariance = -1f        for (step in -30..30) {            val angle = step * 0.5f            val variance = projectionProfileVariance(small, sw, sh, angle)            if (variance > bestVariance) {                bestVariance = variance                bestAngle = angle            }        }        // Only rotate if skew is significant (> 0.5°).        if (Math.abs(bestAngle) < 0.5f) return image        Timber.tag(TAG).d("Deskew: detected skew=${bestAngle}° (variance=$bestVariance).")        // Rotate the full-resolution image by -bestAngle (correct the skew).        return rotateGrayscale(image, -bestAngle)    }    override suspend fun sauvolaThreshold(        image: GrayscaleImage,        windowSize: Int,        k: Float,    ): GrayscaleImage {        if (image.width <= 0 || image.height <= 0) return image        val win = windowSize.coerceAtLeast(3)        val w = image.width        val h = image.height        val src = image.pixels        val dst = ByteArray(w * h)        val half = win / 2        // Compute integral images for mean + squared-mean (for std dev).        // integral[y][x] = sum of pixels in rectangle [0..y, 0..x].        val integral = LongArray((w + 1) * (h + 1))        val integralSq = LongArray((w + 1) * (h + 1))        for (y in 0 until h) {            var rowSum = 0L            var rowSumSq = 0L            for (x in 0 until w) {                val v = src[y * w + x].toInt() and 0xFF                rowSum += v                rowSumSq += v.toLong() * v                integral[(y + 1) * (w + 1) + (x + 1)] =                    integral[y * (w + 1) + (x + 1)] + rowSum                integralSq[(y + 1) * (w + 1) + (x + 1)] =                    integralSq[y * (w + 1) + (x + 1)] + rowSumSq            }        }        for (y in 0 until h) {            val rowStart = y * w            val y0 = (y - half).coerceAtLeast(0)            val y1 = (y + half).coerceAtMost(h - 1)            for (x in 0 until w) {                val x0 = (x - half).coerceAtLeast(0)                val x1 = (x + half).coerceAtMost(w - 1)                val count = ((y1 - y0 + 1) * (x1 - x0 + 1)).coerceAtLeast(1)                // Sum of pixels in window [y0..y1, x0..x1] using integral image.                val sum = integral[(y1 + 1) * (w + 1) + (x1 + 1)] -                    integral[y0 * (w + 1) + (x1 + 1)] -                    integral[(y1 + 1) * (w + 1) + x0] +                    integral[y0 * (w + 1) + x0]                val sumSq = integralSq[(y1 + 1) * (w + 1) + (x1 + 1)] -                    integralSq[y0 * (w + 1) + (x1 + 1)] -                    integralSq[(y1 + 1) * (w + 1) + x0] +                    integralSq[y0 * (w + 1) + x0]                val mean = sum.toFloat() / count                val variance = (sumSq.toFloat() / count) - mean * mean                val stdDev = sqrt(variance.coerceAtLeast(0f))                // Sauvola formula: t = mean * (1 + k * (stdDev / 128 - 1))                val threshold = mean * (1f + k * (stdDev / 128f - 1f))                val pixel = src[rowStart + x].toInt() and 0xFF                // Binarize: pixel < threshold → 0 (black, text), else 255 (white, bg).                dst[rowStart + x] = (if (pixel < threshold) 0 else 255).toByte()            }        }        return GrayscaleImage(w, h, dst)    }    override suspend fun standardDeviation(image: GrayscaleImage): Float {        if (image.width <= 0 || image.height <= 0) return 0f        val n = image.width * image.height        val src = image.pixels        var sum = 0L        for (i in 0 until n) {            sum += src[i].toInt() and 0xFF        }        val mean = sum.toFloat() / n        var sumSqDiff = 0.0        for (i in 0 until n) {            val v = (src[i].toInt() and 0xFF) - mean            sumSqDiff += v * v        }        return sqrt((sumSqDiff / n).toFloat())    }    // ─── Internal helpers ──────────────────────────────────────────────────    /** Convert a [Bitmap] to an [RgbImage] (RGB triplet byte array). */    private fun bitmapToRgbImage(bitmap: Bitmap): RgbImage {        val w = bitmap.width        val h = bitmap.height        val argbPixels = IntArray(w * h)        bitmap.getPixels(argbPixels, 0, w, 0, 0, w, h)        val rgbBytes = ByteArray(w * h * 3)        for (i in argbPixels.indices) {            val argb = argbPixels[i]            rgbBytes[i * 3] = ((argb shr 16) and 0xFF).toByte()      // R            rgbBytes[i * 3 + 1] = ((argb shr 8) and 0xFF).toByte()   // G            rgbBytes[i * 3 + 2] = (argb and 0xFF).toByte()           // B        }        return RgbImage(w, h, rgbBytes)    }    /** Nearest-neighbor downsample of a grayscale image. */    private fun downsampleGrayscale(        src: ByteArray,        srcW: Int,        srcH: Int,        dstW: Int,        dstH: Int,    ): ByteArray {        val dst = ByteArray(dstW * dstH)        for (y in 0 until dstH) {            val sy = (y * srcH / dstH).coerceIn(0, srcH - 1)            for (x in 0 until dstW) {                val sx = (x * srcW / dstW).coerceIn(0, srcW - 1)                dst[y * dstW + x] = src[sy * srcW + sx]            }        }        return dst    }    /**     * Compute the variance of the horizontal projection profile after     * rotating by [angleDeg]. Higher variance = sharper text rows = likely skew.     */    private fun projectionProfileVariance(        src: ByteArray,        w: Int,        h: Int,        angleDeg: Float,    ): Float {        val angleRad = Math.toRadians(angleDeg.toDouble())        val cosA = cos(angleRad).toFloat()        val sinA = sin(angleRad).toFloat()        val cx = w / 2f        val cy = h / 2f        // Project each pixel onto the rotated y-axis.        val profile = FloatArray(h)        for (y in 0 until h) {            for (x in 0 until w) {                val dx = x - cx                val dy = y - cy                val newY = (dy * cosA - dx * sinA + cy).toInt()                if (newY in 0 until h) {                    val pixel = src[y * w + x].toInt() and 0xFF                    // Use darkness (255 - pixel) so text rows have high values.                    profile[newY] += 255 - pixel                }            }        }        // Compute variance of the profile.        val mean = profile.average().toFloat()        var sumSqDiff = 0.0        for (v in profile) {            val d = v - mean            sumSqDiff += d * d        }        return (sumSqDiff / h).toFloat()    }    /** Rotate a grayscale image by [angleDeg] (counter-clockwise). */    private fun rotateGrayscale(image: GrayscaleImage, angleDeg: Float): GrayscaleImage {        val w = image.width        val h = image.height        val src = image.pixels        val angleRad = Math.toRadians(angleDeg.toDouble())        val cosA = cos(angleRad).toFloat()        val sinA = sin(angleRad).toFloat()        val cx = w / 2f        val cy = h / 2f        val dst = ByteArray(w * h)        // For each destination pixel, sample the source via inverse rotation.        for (y in 0 until h) {            for (x in 0 until w) {                val dx = x - cx                val dy = y - cy                // Inverse rotation: src = R(-angle) * dst.                val srcX = (dx * cosA + dy * sinA + cx).toInt()                val srcY = (-dx * sinA + dy * cosA + cy).toInt()                dst[y * w + x] = if (srcX in 0 until w && srcY in 0 until h) {                    src[srcY * w + srcX]                } else {                    255.toByte()  // White background for out-of-bounds.                }            }        }        return GrayscaleImage(w, h, dst)    }    private companion object {        private const val TAG = "AndroidImageProcessor"    }}